// - "api" refers to personal API access tokens or tokens generated using an OAuth client or federated identity.
type KeyKeyType string

// KeyCapabilities `capabilities` is a mapping of resources to permissible actions.
type KeyCapabilities struct {
	// Devices `devices` specifies the key's permissions over devices.
	// This field is only populated for auth keys.
	Devices *struct {
		// Create `create` specifies the key's permissions when creating devices.
		Create *struct {
			// Ephemeral ephemeral for auth keys only; ephemeral keys are used to connect and then clean up short-lived devices.
			// Learn about ephemeral nodes at https://tailscale.com/docs/features/ephemeral-nodes.
			Ephemeral *bool `json:"ephemeral,omitempty"`

			// Preauthorized preauthorized for auth keys only; these are also referred to as "pre-approved" keys. 'true' means that devices
			// registered with this key won't require additional approval from a tailnet admin.
			// Learn about device approval at https://tailscale.com/docs/features/access-control/device-management/device-approval.
			Preauthorized *bool `json:"preauthorized,omitempty"`

			// Reusable reusable for auth keys only; reusable auth keys can be used multiple times to register different devices.
			// Learn more about reusable auth keys at https://tailscale.com/docs/features/access-control/auth-keys#types-of-auth-keys.
			Reusable *bool `json:"reusable,omitempty"`

			// Tags tags are the tags that will be set on devices registered with this key.
			// Learn about tags at https://tailscale.com/docs/features/tags.
			//
			// Whether tags are required or optional depends on the owner of the auth key:
			// - When creating an auth key owned by the tailnet (using OAuth), it must have tags. The auth tags specified for that new auth key must exactly match the tags that are on the OAuth client used to create that auth key (or they must be tags that are owned by the tags that are on the OAuth client used to create the auth key).
			// - When creating an auth key owned by a user (using a user's access token), tags are optional.
			Tags *[]string `json:"tags,omitempty"`
		} `json:"create,omitempty"`
	} `json:"devices,omitempty"`
}

