// AcceptDeviceInviteWithBody Accept a device invite
//
// Accepts the invitation to share a device into the requesting user's tailnet.
//
// Note that device invites cannot be accepted using an API access token generated from an OAuth client as the shared device is scoped to a user.
//
// Takes any type of body and a specified content type.
//
// Corresponds with POST /device-invites/-/accept (the `AcceptDeviceInvite` operationId).
func (c *Client) AcceptDeviceInviteWithBody(ctx context.Context, contentType string, body io.Reader, reqEditors ...RequestEditorFn) (*http.Response, error) {
	req, err := NewAcceptDeviceInviteRequestWithBody(c.Server, contentType, body)
	if err != nil {
		return nil, err
	}
	req = req.WithContext(ctx)
	if err := c.applyEditors(ctx, req, reqEditors); err != nil {
		return nil, err
	}
	return c.Client.Do(req)
}

